import {
	act,
	render,
	waitFor,
} from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const bridge = vi.hoisted(() => ({
	callServerTool: vi.fn().mockResolvedValue({ isError: false }),
	close: vi.fn(),
	connect: vi.fn().mockResolvedValue(undefined),
	hostContext: {} as Record<string, unknown>,
	listeners: new Map<string, Set<(params: unknown) => void>>(),
}));

vi.mock("@modelcontextprotocol/ext-apps", () => ({
	App: class {
		addEventListener(name: string, handler: (params: unknown) => void) {
			const handlers = bridge.listeners.get(name) ?? new Set();
			handlers.add(handler);
			bridge.listeners.set(name, handlers);
		}
		removeEventListener(name: string, handler: (params: unknown) => void) {
			bridge.listeners.get(name)?.delete(handler);
		}
		callServerTool = bridge.callServerTool;
		connect = bridge.connect;
		getHostContext() {
			return { theme: "light", ...bridge.hostContext };
		}
		async openLink() {
			return { isError: false };
		}
	},
	PostMessageTransport: class {
		close = bridge.close;
	},
}));

type CompatParent = EventTarget & {
	location: { origin: string };
};

const originalParentDescriptor = Object.getOwnPropertyDescriptor(window, "parent");
const originalOpenAiDescriptor = Object.getOwnPropertyDescriptor(window, "openai");

function restoreWindowProperty(
	name: "parent" | "openai",
	descriptor: PropertyDescriptor | undefined,
) {
	if (descriptor) Object.defineProperty(window, name, descriptor);
	else Reflect.deleteProperty(window, name);
}

describe("review restore races", () => {
	beforeEach(() => {
		vi.resetModules();
		vi.clearAllMocks();
		bridge.listeners.clear();
		bridge.hostContext = {};
		bridge.callServerTool.mockResolvedValue({ isError: false });
	});

	afterEach(() => {
		restoreWindowProperty("parent", originalParentDescriptor);
		restoreWindowProperty("openai", originalOpenAiDescriptor);
	});

	it("saves before an in-flight restore finishes", async () => {
		const compatParent: CompatParent = Object.assign(new EventTarget(), {
			location: { origin: "https://chatgpt.com" },
		});
		Object.defineProperty(window, "parent", { configurable: true, value: compatParent });
		Object.defineProperty(window, "openai", {
			configurable: true,
			value: { toolOutput: { title: "Current replayed result" } },
		});
		bridge.hostContext = {
			toolInfo: { id: "bound-card-race", tool: { name: "query_sdk" } },
		};
		let resolveConnect!: () => void;
		const connect = new Promise<void>((resolve) => { resolveConnect = resolve; });
		bridge.connect.mockReturnValue(connect);
		let resolveRestore!: (value: unknown) => void;
		const restore = new Promise((resolve) => { resolveRestore = resolve; });
		bridge.callServerTool.mockImplementation(async ({ name }) => {
			if (name === "restore_lobu_app_result") return restore;
			if (name === "save_lobu_app_state") {
				return { isError: false, structuredContent: { saved: true } };
			}
			return { isError: false };
		});

		const { Provider } = await import("./host");
		render(<Provider devMock={{ title: "Development result" }}><span>Probe</span></Provider>);
		await waitFor(() => expect(bridge.listeners.get("hostcontextchanged")?.size).toBe(1));
		act(() => {
			for (const handler of bridge.listeners.get("hostcontextchanged") ?? []) {
				handler({ theme: "light" });
			}
		});
		await waitFor(() => expect(
			bridge.callServerTool.mock.calls.filter(([r]) => r.name === "restore_lobu_app_result"),
		).toHaveLength(1));
		await act(async () => { resolveConnect(); await connect; });
		await waitFor(() => expect(
			bridge.callServerTool.mock.calls.filter(([r]) => r.name === "save_lobu_app_state"),
		).toHaveLength(1));
		resolveRestore({
			isError: false,
			structuredContent: {
				found: true,
				tool_name: "query_sdk",
				data: { title: "Historical" },
				view_state: { "details.open": true },
			},
		});
	});

	it("saves after a failed restore", async () => {
		const compatParent: CompatParent = Object.assign(new EventTarget(), {
			location: { origin: "https://chatgpt.com" },
		});
		Object.defineProperty(window, "parent", { configurable: true, value: compatParent });
		Object.defineProperty(window, "openai", {
			configurable: true,
			value: { toolOutput: { title: "Current replayed result" } },
		});
		bridge.hostContext = {
			toolInfo: { id: "bound-card-error", tool: { name: "query_sdk" } },
		};
		bridge.callServerTool.mockImplementation(async ({ name }) => {
			if (name === "restore_lobu_app_result") throw new Error("temporary");
			if (name === "save_lobu_app_state") {
				return { isError: false, structuredContent: { saved: true } };
			}
			return { isError: false };
		});

		const { Provider } = await import("./host");
		render(<Provider devMock={{ title: "Development result" }}><span>Probe</span></Provider>);
		await waitFor(() => expect(
			bridge.callServerTool.mock.calls.filter(([r]) => r.name === "save_lobu_app_state"),
		).toHaveLength(1));
	});
});

